"use server";

import { requireRole } from "@/lib/acl";
import { db } from "@/lib/db";
import { readJson } from "@/lib/db/json";
import { llm, resolveUsableModel } from "@/lib/llm";
import { brandContextBlock } from "@/lib/motifs";
import { networkFor } from "@/lib/social/networks";
import { hit } from "@/lib/rate-limit";
import { TAG_RE as TAG_IN_TEXT, howManyTags } from "@/lib/social/hashtag-text";
import { houseTags } from "@/lib/social/house-tags";

/**
 * Hashtags for a post, from the brand and its Topic (2026-11-21, the owner: "I want hashtags autogenerated
 * (brand/topic appropriate)"). The composer asks once by itself when a post has enough to go on, and again on
 * Refresh; the tags come back as chips, and nothing goes into the post until the person clicks one or "Add".
 *
 * ⚠ The client sends the post's TEXT, its Topic's id and the network slugs — never a prompt (the key-not-prompt rule
 * the tailor and assist follow), so a browser can't spend the workspace's model budget on its own instructions.
 * ⚠ PROPOSES, never applies. ⚠ Mock output is refused: a placeholder tag in a real feed is the failure this app keeps
 * re-learning. ⚠ It refuses rather than guessing from nothing — the brand name alone is not grounding.
 *
 * Grounding, all read here on the server: the brand facts and guardrails (brandContextBlock), the workspace's name,
 * the Topic's name and keywords, and the hashtags already in its saved hashtag sets (social snippets) — the brand's
 * own house tags, offered first and kept spelled as saved.
 */

export type HashtagKind = "brand" | "topic" | "post";
export type HashtagSuggestion = { tag: string; kind: HashtagKind };
export type HashtagResult =
  | { ok: true; tags: HashtagSuggestion[]; provider: string; advice: string; addCount: number }
  | { ok: false; error: string };

/** A hashtag every network accepts: "#", then letters, digits or underscores of any script, at least one letter. */
const TAG = /^#[\p{L}\p{N}_]*[\p{L}_][\p{L}\p{N}_]*$/u;

export async function suggestHashtagsAction(input: {
  text: string;
  topicId?: string | null;
  /** Zernio platform slugs of the selected accounts. */
  providers?: string[];
}): Promise<HashtagResult> {
  const { workspace, user } = await requireRole("EDITOR");
  const text = String(input.text ?? "").slice(0, 4000);
  const words = text.replace(TAG_IN_TEXT, " ").replace(/https?:\/\/\S+/g, " ").trim();
  const providers = [...new Set((input.providers ?? []).map((p) => String(p).toLowerCase()))].filter((p) => networkFor(p)).slice(0, 15);

  const topic = input.topicId
    ? await db.topic.findFirst({ where: { id: String(input.topicId), workspaceId: workspace.id }, select: { name: true, keywords: true } })
    : null;
  if (words.length < 20 && !topic) {
    return { ok: false, error: "Write a sentence or two, or pick a Topic, and hashtags will be suggested from it." };
  }

  const limit = await hit("hashtagsPerUser", user.id);
  if (!limit.ok) return { ok: false, error: `Hashtags were asked for many times just now — try again in ${limit.retryAfter} s.` };

  // The brand's own tags (lib/social/house-tags.ts), spelled as saved — the same list the engine's writer is given.
  const house = await houseTags(workspace.id);
  const already = new Set((text.match(TAG_IN_TEXT) ?? []).map((t) => t.toLowerCase()));
  const keywords = topic ? readJson<string[]>(topic.keywords, []).slice(0, 15) : [];
  const guardrails = await brandContextBlock(workspace.id).catch(() => null);
  const { count, advice } = howManyTags(providers);

  const system =
    "You suggest hashtags for one social media post. Return ONLY JSON: {\"tags\":[{\"tag\":\"#Example\",\"kind\":\"brand|topic|post\"}]}. " +
    "Twelve tags at most, best first. kind: \"brand\" = the company's own or house tags, \"topic\" = the subject area the post belongs to, " +
    "\"post\" = specific to what this post says. Use tags people really follow and search; CamelCase multi-word tags; no spaces or punctuation; " +
    "never a tag already in the post; never invent a product, event or claim the post and brand facts don't support; no generic filler such as #Love, #Instagood, #FollowMe.";
  const prompt = [
    `Company: ${workspace.name}`,
    guardrails ?? "",
    house.length ? `The company's saved hashtags (offer the ones that fit this post first, spelled exactly like this): ${house.join(" ")}` : "",
    topic ? `Topic: ${topic.name}${keywords.length ? ` — related phrases: ${keywords.join(", ")}` : ""}` : "",
    providers.length ? `It will go to: ${providers.map((p) => networkFor(p)?.label ?? p).join(", ")}.` : "",
    `The post:\n"""\n${text.trim() || "(not written yet — suggest from the Topic and the company)"}\n"""`,
  ].filter(Boolean).join("\n\n");

  try {
    const model = await resolveUsableModel("", workspace.id, "social.hashtags");
    const res = await llm.complete({
      purpose: "social.hashtags",
      model,
      system,
      messages: [{ role: "user", content: prompt }],
      workspaceId: workspace.id,
      temperature: 0.5,
      maxTokens: 800,
    });
    const provider = res.provider ?? "unknown";
    if (provider === "mock") {
      return { ok: false, error: "The model wasn't reachable, so no hashtags were suggested (placeholder tags are never offered)." };
    }
    const tags = parseTags(res.content, already, house);
    if (!tags.length) return { ok: false, error: "The model didn't return usable hashtags. Try Refresh." };
    return { ok: true, tags, provider, advice, addCount: Math.min(count, tags.length) };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message.slice(0, 200) : "Hashtags couldn't be suggested." };
  }
}

/** Pull valid, new, de-duplicated tags out of the reply; a house tag keeps its saved spelling and counts as brand. */
function parseTags(raw: string, already: Set<string>, house: string[]): HashtagSuggestion[] {
  const cleaned = (raw ?? "").trim().replace(/^```(?:json)?\n?/i, "").replace(/\n?```$/, "").trim();
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  let list: unknown[] = [];
  if (start >= 0 && end > start) {
    try {
      const obj = JSON.parse(cleaned.slice(start, end + 1)) as { tags?: unknown };
      if (Array.isArray(obj.tags)) list = obj.tags;
    } catch {
      list = [];
    }
  }
  const houseBy = new Map(house.map((h) => [h.toLowerCase(), h]));
  const seen = new Set<string>();
  const out: HashtagSuggestion[] = [];
  for (const item of list) {
    const o = (typeof item === "string" ? { tag: item } : item) as { tag?: unknown; kind?: unknown };
    let tag = String(o?.tag ?? "").trim().replace(/\s+/g, "");
    if (!tag) continue;
    if (!tag.startsWith("#")) tag = `#${tag}`;
    if (!TAG.test(tag) || tag.length > 60) continue;
    const low = tag.toLowerCase();
    if (already.has(low) || seen.has(low)) continue;
    seen.add(low);
    const saved = houseBy.get(low);
    const kind: HashtagKind = saved ? "brand" : o?.kind === "brand" || o?.kind === "topic" ? (o.kind as HashtagKind) : "post";
    out.push({ tag: saved ?? tag, kind });
    if (out.length >= 12) break;
  }
  return out;
}
